$JobExecScript = 'C:\Users\jinbeom\.claude\tools\cpu-scheduler\job_exec.py'
$JobLimitArguments = @('--memory-mb', '6000')
$JobKillOnClose = $true
$ReserveScript = 'C:\Users\jinbeom\.claude\tools\cpu-scheduler\reserve.py'
$ReserveOwner = 'c4g2k1-E1'
$ReserveTtlMin = 240
$ReserveMaskHex = '0xFF0000'
$ReserveGpu = $null

$JobArguments = @($JobLimitArguments)
if ($JobKillOnClose) { $JobArguments += @('--kill-on-close', '--runner-pid', "$PID") }
Write-Output "[job] each step runs in a Job object: $($JobArguments -join ' ')"

$self = [System.Diagnostics.Process]::GetCurrentProcess()
$self.PriorityClass = $Priority
if ($null -ne $RunnerMask) { $self.ProcessorAffinity = [IntPtr][long]$RunnerMask }
New-Item -ItemType Directory -Force -Path $LogDir | Out-Null

function Write-Log([string]$Text, [string]$LogPath) {
    $Text | Tee-Object -FilePath $LogPath -Append -Encoding utf8 | Out-Host
}

# Runs one program, echoes and appends its output to $LogPath, returns its
# exit code (-1 when it could not be started).
function Invoke-Logged([string]$File, [string[]]$Arguments, [string]$LogPath) {
    $global:LASTEXITCODE = $null
    try {
        & $File @Arguments 2>&1 | ForEach-Object { "$_" } |
            Tee-Object -FilePath $LogPath -Append -Encoding utf8 | Out-Host
        $code = $global:LASTEXITCODE
    } catch {
        Write-Log "[error] $_" $LogPath
        $code = $null
    }
    if ($null -eq $code) { return -1 }
    return [int]$code
}

if ($null -ne $WaitArguments) {
    $waitLog = Join-Path $LogDir $WaitLogName
    $waitCommand = @('-I', $WaitScript) + $WaitArguments
    $waitCode = Invoke-Logged $WaitPython $waitCommand $waitLog
    if ($waitCode -ne 0) {
        Write-Log "[stop] wait_until exit=$waitCode; no step started" $waitLog
        exit $waitCode
    }
}


$ReserveId = $null
# Runs reserve.py and returns its JSON answer ($null if it printed none).
function Invoke-Reserve([string[]]$ReserveArguments) {
    $text = & $WaitPython -I $ReserveScript @ReserveArguments 2>$null | Out-String
    try { return ($text | ConvertFrom-Json) } catch { return $null }
}
function Register-Reservation {
    $arguments = @('add', '--owner', $ReserveOwner, '--pid', "$PID",
        '--ttl-min', "$ReserveTtlMin", '--mask', $ReserveMaskHex)
    if ($null -ne $ReserveGpu) { $arguments += @('--gpu', "$ReserveGpu") }
    $answer = Invoke-Reserve $arguments
    if ($null -eq $answer -or -not $answer.id) {
        Write-Output "[reserve] warning: not registered; steps run anyway"
        return
    }
    $script:ReserveId = $answer.id
    Write-Output "[reserve] $($answer.id) owner=$ReserveOwner mask=$ReserveMaskHex"
    foreach ($conflict in $answer.conflicts) {
        Write-Output ("[reserve] overlaps {0} owner={1} logical={2}" -f $conflict.id,
            $conflict.owner, ($conflict.overlap_logical -join ','))
    }
}
# Renews before each step; a lease that expired and was pruned is registered again.
function Update-Reservation {
    if ($null -ne $script:ReserveId) {
        $answer = Invoke-Reserve @('renew', '--id', $script:ReserveId)
        if ($null -ne $answer -and $answer.id) { return }
        $script:ReserveId = $null
    }
    Register-Reservation
}
Register-Reservation
try {
    $failedSteps = @()
    foreach ($step in $Steps) {
        $log = Join-Path $LogDir "$($step.Id).log"
        $doneMarker = Join-Path $LogDir "$($step.Id).done"
        if ($SkipDone -and (Test-Path -LiteralPath $doneMarker)) {
            Write-Log "[skip] $($step.Id) already done" $log
            continue
        }
        Update-Reservation
        if ($null -ne $step.Mask) { $self.ProcessorAffinity = [IntPtr][long]$step.Mask }
        $savedEnv = @{}
        foreach ($name in $step.Env.Keys) {
            $savedEnv[$name] = [Environment]::GetEnvironmentVariable($name)
            [Environment]::SetEnvironmentVariable($name, $step.Env[$name])
        }
        $gpuProcess = $null
        if ($GpuLog) {
            $gpuProcess = Start-Process -FilePath 'nvidia-smi' -NoNewWindow -PassThru `
                -ArgumentList "--query-gpu=$GpuQuery", '--format=csv', `
                    '-l', "$GpuLogIntervalS" `
                -RedirectStandardOutput (Join-Path $LogDir "$($step.Id).gpu.csv")
        }
        if ($step.Cwd) { Push-Location -LiteralPath $step.Cwd }
        $started = Get-Date
        Write-Log ("[start] {0} {1} mask=0x{2:X} priority={3}" -f $step.Id,
            $started.ToString('s'), [long]$self.ProcessorAffinity, $Priority) $log
        try {
            $jobCommand = @('-I', $JobExecScript) + $JobArguments + @('--', $step.File) + $step.Arguments
            $code = Invoke-Logged $WaitPython $jobCommand $log
        } finally {
            if ($step.Cwd) { Pop-Location }
            if ($null -ne $gpuProcess) {
                Stop-Process -Id $gpuProcess.Id -ErrorAction SilentlyContinue
            }
            foreach ($name in $savedEnv.Keys) {
                if ($null -eq $savedEnv[$name]) {
                    Remove-Item -LiteralPath "Env:$name" -ErrorAction SilentlyContinue
                } else {
                    [Environment]::SetEnvironmentVariable($name, $savedEnv[$name])
                }
            }
        }
        $wallS = [int]((Get-Date) - $started).TotalSeconds
        Write-Log "[end] $($step.Id) exit=$code wall_s=$wallS" $log
        if ($code -eq 0) {
            Set-Content -LiteralPath $doneMarker -Encoding utf8 `
                -Value "$((Get-Date).ToString('s')) exit=0 wall_s=$wallS"
            continue
        }
        $failedSteps += $step.Id
        if ($StopOnFail) {
            Write-Output "[stop] $($step.Id) failed (exit=$code); later steps NOT started"
            exit 1
        }
    }
    if ($failedSteps.Count -gt 0) {
        Write-Output "[done] failed steps: $($failedSteps -join ', ')"
        exit 1
    }
    Write-Output '[done] all steps complete'
    exit 0
} finally {
    if ($null -ne $ReserveId) {
        Invoke-Reserve @('release', '--id', $ReserveId) | Out-Null
        Write-Output "[reserve] released $ReserveId"
    }
}
